```html
<cu-collapse id="miCollapse" label="Programático">
  <p>Controlado desde JS con open()/close()/toggle().</p>
</cu-collapse>

<script>
  const c = document.getElementById('miCollapse');
  c.open();
  c.close();
  c.toggle();
  c.isOpen(); // boolean
</script>
